import { PASSWORD, USERS, expect, test } from "../../fixtures";

test("successful sign-in returns a session", { tag: "@AUTH-01" }, async ({ request }) => {
  const response = await request.post("/api/auth/login", {
    data: { email: USERS.member, password: PASSWORD },
  });

  const bodyText = await response.text();
  expect(response.status(), bodyText).toBe(200);

  const body = JSON.parse(bodyText);
  expect(typeof body.access_token, bodyText).toBe("string");
  expect(body.access_token.length, bodyText).toBeGreaterThan(0);
  expect(body.user?.email, bodyText).toBe("member@northwind.test");
  expect(body.user?.role, bodyText).toBe("member");
  expect(body.user?.tenant?.name, bodyText).toBe("Northwind Supply");

  const cookies = response
    .headersArray()
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .map((h) => h.value);
  const session = cookies.find((c) => /^session=/.test(c.trim()));
  expect(session, `set-cookie headers: ${JSON.stringify(cookies)}`).toBeTruthy();
  expect(session!.split(";")[0].trim().length, session).toBeGreaterThan("session=".length);
  expect(session!.toLowerCase(), session).toMatch(/;\s*httponly/);
});
